import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {readWork,authorizationDigest} from './scripts/workflow/work.ts';
const root=process.argv[1], childId=process.argv[2], parentId=process.argv[3], traceFile=process.argv[4];
const sha=value=>createHash('sha256').update(value).digest('hex');
const baseline=await readFile(root+'/baseline-proof.md','utf8');
const review=await readFile(root+'/current-review.md','utf8');
const heading=review.indexOf('## 18개실제교정과원문문맥');
assert.notEqual(heading,-1);
const start=review.indexOf('{',heading), end=review.indexOf('\n}',start);
const {patches}=JSON.parse(review.slice(start,end+2));
assert.equal(patches.length,18);
const fence=String.fromCharCode(96).repeat(4);
const sections=new RegExp('^## (skill-library/[^\\n]+) — before SHA ([0-9a-f]{64})\\n\\n'+fence+'\\n(.*?)^'+fence+'$','gms');
const seen=new Set();
let applied=0;
const files=[];
for(const match of baseline.matchAll(sections)){
 const [,file,digest,display]=match;
 assert(!seen.has(file));
 seen.add(file);
 const actual=await readFile(file);
 let source=display;
 if(file.endsWith('/capy-pr.md')){
  const displayed=source.split('\n').find(line=>line.includes('[<caption>]'));
  const literal=actual.toString('utf8').split('\n').find(line=>line.includes('[<caption>]'));
  assert(displayed&&literal&&displayed!==literal);
  source=source.replace(displayed,literal);
 }
 const originals=[source,source.endsWith('\n')?source.slice(0,-1):source];
 const original=originals.find(bytes=>sha(bytes)===digest);
 assert(original!==undefined,'교정 전 저장 지문과 다릅니다: '+file);
 let replaced=original;
 for(const patch of patches.filter(row=>row.path===file)){
  assert.equal(patch.sha256,digest);
  assert.equal(replaced.split(patch.old).length,2);
  replaced=replaced.replace(patch.old,patch.new);
  applied++;
 }
 assert.deepEqual(Buffer.from(replaced),actual,'현재 파일에 교정 이외 차이가 있습니다: '+file);
 files.push({file,beforeSha256:digest,currentSha256:sha(actual)});
}
assert.equal(seen.size,7);
assert.equal(applied,18);
const evidence=JSON.parse(await readFile(traceFile,'utf8'));
const child=(await readWork({workId:childId})).record;
const parent=(await readWork({workId:parentId})).record;
assert.equal(evidence.child,child.id);
assert.equal(evidence.parent,parent.id);
assert(child.relations.some(edge=>edge.type==='relates_to'&&edge.target===parent.id));
assert.equal(authorizationDigest(parent.workflow.authorization),evidence.parentAuthorizationDigest);
assert.deepEqual(parent.workflow.authorization.verifierCommands,evidence.parentApprovalCommands);
assert(evidence.parentFailures.length>0&&evidence.childFailures.length>0);
for(const [work,list] of [[parent,evidence.parentFailures],[child,evidence.childFailures]]){
 const retained=new Set(work.workflow.verifications.filter(row=>row.result==='failed').map(row=>row.id));
 assert(list.every(id=>retained.has(id)));
}
console.log(JSON.stringify({applied,files,parent:parent.id,child:child.id,priorParentFailures:evidence.parentFailures.length,priorChildFailures:evidence.childFailures.length}));
