import assert from "node:assert/strict";
import {execFileSync} from "node:child_process";
import {readFileSync} from "node:fs";
import {createHash} from "node:crypto";
const [relative,childFile,parentFile,rev,rawRoot,replay]=process.argv.slice(1);
const current=JSON.parse(readFileSync(childFile));
const parent=JSON.parse(readFileSync(parentFile));
const older=path=>JSON.parse(execFileSync("git",["show",rev+":"+path]));
const historicParent=older(parentFile),historicChild=older(childFile);
assert.equal(historicParent.id,parent.id);
assert.equal(historicChild.id,current.id);
assert.deepEqual(parent.workflow.authorization,historicParent.workflow.authorization);
assert.equal(parent.workflow.requestId,historicParent.workflow.requestId);
assert.equal(parent.workflow.requestHash,historicParent.workflow.requestHash);
assert.deepEqual(parent.workflow.verifierAuthorizations,historicParent.workflow.verifierAuthorizations);
for(const [before,after] of [[historicParent,parent],[historicChild,current]]){
  for(const old of before.workflow.verifications.filter(v=>v.result==="failed"))assert.deepEqual(after.workflow.verifications.find(v=>v.id===old.id),old);
  for(const old of before.workflow.reviews.filter(v=>v.verdict==="fail"))assert.deepEqual(after.workflow.reviews.find(v=>v.id===old.id),old);
}
assert.ok(current.relations.some(v=>v.type==="relates_to"&&v.target===parent.id));
const review=readFileSync(relative+"/current-review.md","utf8");
const start=review.indexOf("{",review.indexOf("## 18개실제교정과원문문맥")),end=review.indexOf("\n}",start);
const {patches}=JSON.parse(review.slice(start,end+2));
const inventory=JSON.parse(readFileSync("skill-library/inventory.json"));
assert.equal(patches.length,18);
let linesVerified=0;
const seen=new Set();
for(const patch of patches){
 const item=inventory.files.find(file=>file.localPath===patch.path);
 assert.ok(item);
 const bytes=readFileSync(rawRoot+"/"+item.source+"/"+item.originPath);
 assert.equal(bytes.length,item.originalBytes);
 assert.equal(createHash("sha256").update(bytes).digest("hex"),item.originalSha256);
 const lines=bytes.toString("utf8").split(/\r?\n/);
 for(const entry of patch.originalLines){ assert.equal(lines[entry.line-1],entry.text); linesVerified++; }
 seen.add(patch.path);
}
assert.equal(linesVerified,92);
assert.equal(seen.size,7);
execFileSync(process.execPath,JSON.parse(replay),{stdio:"inherit"});
console.log(JSON.stringify({parent:parent.id,priorAuthorizations:historicParent.workflow.authorization.verifierCommands.length,priorFailures:historicParent.workflow.verifications.filter(v=>v.result==="failed").length,checkpoint:rev,files:seen.size,patches:patches.length,linesVerified}));
