import {execFileSync} from "node:child_process";
import {readFileSync} from "node:fs";
import {createHash} from "node:crypto";
const revision=process.argv[1];
const get=path=>execFileSync("git",["show",revision+":"+path]);
const hash=bytes=>createHash("sha256").update(bytes).digest("hex");
const inventory="skill-library/inventory.json";
const sources="skill-library/sources.json";
assert.deepEqual(get(sources),readFileSync(sources));
const before=JSON.parse(get(inventory));
const after=JSON.parse(readFileSync(inventory));
assert.equal(before.files.length,201);
assert.equal(after.files.length,201);
assert.equal(after.files.filter(file=>file.language==="ko").length,186);
assert.equal(after.files.filter(file=>file.language==="original").length,15);
const current=new Map(after.files.map(file=>[file.localPath,file]));
assert.equal(current.size,201);
let localChanged=0;
for(const beforeFile of before.files){
 const item=current.get(beforeFile.localPath);
 assert.ok(item,beforeFile.localPath);
 const {sha256:priorHash,bytes:priorBytes,...priorMetadata}=beforeFile;
 const {sha256:currentHash,bytes:currentBytes,...currentMetadata}=item;
 assert.deepEqual(priorMetadata,currentMetadata);
 const old=get(item.localPath);
 const contents=readFileSync(item.localPath);
